const APP = "(()=>{\"use strict\";const levels=[{pattern:\"🔵 🔴 🔵 🔴 ❓\",choices:[\"🔵\",\"🔴\",\"🟡\"],labels:[\"círculo azul\",\"círculo vermelho\",\"círculo amarelo\"],answer:0,hint:\"As cores se alternam: azul, vermelho, azul, vermelho...\"},{pattern:\"▲ ▲ ● ▲ ▲ ● ❓\",choices:[\"●\",\"▲\",\"■\"],labels:[\"círculo\",\"triângulo\",\"quadrado\"],answer:1,hint:\"Duas formas iguais, depois uma diferente.\"},{pattern:\"2 · 4 · 6 · 8 · ❓\",choices:[\"9\",\"12\",\"10\"],labels:[\"nove\",\"doze\",\"dez\"],answer:2,hint:\"Os números aumentam de dois em dois.\"},{pattern:\"🌱 🌿 🌳 🌱 🌿 ❓\",choices:[\"🌱\",\"🌳\",\"🌿\"],labels:[\"broto\",\"árvore\",\"planta\"],answer:1,hint:\"Primeiro cresce, depois vira árvore, e recomeça.\"}];let index=0,locked=false;const $=id=>document.getElementById(id);const pattern=$(\"pattern\"),choices=$(\"choices\"),feedback=$(\"feedback\"),stage=$(\"stage\"),next=$(\"next\"),restart=$(\"restart\");function render(){const q=levels[index];locked=false;pattern.textContent=q.pattern;stage.textContent=\"Desafio \"+(index+1)+\" de \"+levels.length;feedback.textContent=\"Escolha uma opção para começar! 🌟\";choices.replaceChildren();q.choices.forEach((item,i)=>{const b=document.createElement(\"button\");b.type=\"button\";b.dataset.answer=String(i);b.setAttribute(\"aria-label\",\"Opção \"+(i+1)+\": \"+q.labels[i]);b.textContent=item;choices.append(b)});next.hidden=true;restart.hidden=true}choices.addEventListener(\"click\",e=>{const b=e.target.closest(\"button[data-answer]\");if(!b||locked)return;const q=levels[index],picked=Number(b.dataset.answer);if(picked!==q.answer){b.classList.add(\"wrong\");feedback.textContent=\"Quase! Dica: \"+q.hint+\" Tente outra vez 💜\";return}locked=true;b.classList.add(\"correct\");for(const button of choices.querySelectorAll(\"button\"))button.disabled=true;feedback.textContent=index===levels.length-1?\"Parabéns! Você completou a missão! 🏆\":\"Isso mesmo! Você encontrou o padrão! ✨\";if(index===levels.length-1){restart.hidden=false}else{next.hidden=false}});next.addEventListener(\"click\",()=>{if(index<levels.length-1){index++;render();choices.querySelector(\"button\")?.focus()}});restart.addEventListener(\"click\",()=>{index=0;render();choices.querySelector(\"button\")?.focus()});render()})();";
const GAME_HTML = "<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#eeecff\"><meta name=\"description\" content=\"Jogo gratuito de programação para crianças: ajude a lobinha Heart a encontrar cristais usando comandos e repetições.\"><title>A Heart e a Missão dos Algoritmos | Workshop Kids</title><link rel=\"stylesheet\" href=\"/game.css\"></head>\n<body><a class=\"skip\" href=\"#jogo\">Pular para o jogo</a>\n<header class=\"top\"><a class=\"brand\" href=\"/\">✦ <span>THE WORKSHOP <strong>KIDS</strong></span></a><a class=\"back\" href=\"/blade/\">🛡️ Blade</a><a class=\"back\" href=\"/jogos/\">🎮 Game Lab</a><a class=\"back\" href=\"/\">← Voltar à oficina</a></header>\n<main id=\"jogo\"><section class=\"intro\"><div><p class=\"eyebrow\">🐺 KIDS CODE • PRIMEIRA AVENTURA</p><h1>A Heart e a <em>Missão dos Algoritmos</em></h1><p>Você é a pessoa programadora! Dê instruções para a Heart encontrar o cristal. Cada comando é uma peça do seu algoritmo.</p></div><div class=\"mascot game-heart-portrait\"><img src=\"/assets/heart.webp?v=00ff52e6\" width=\"640\" height=\"640\" alt=\"Heart, a lobinha netrunner que você programa\" decoding=\"async\"></div></section>\n<div class=\"level-header\"><div><p class=\"eyebrow\" id=\"level-count\">FASE 1 DE 5</p><h2 id=\"level-title\">Primeiros passos</h2><p id=\"level-story\">Ajude a Heart a chegar ao cristal.</p></div><div class=\"progress\" role=\"group\" aria-label=\"Progresso das fases\"><span class=\"dot current\">1</span><span class=\"dot\">2</span><span class=\"dot\">3</span><span class=\"dot\">4</span><span class=\"dot\">5</span></div></div>\n<div class=\"workspace\"><section class=\"board-panel\" aria-labelledby=\"map-title\"><div class=\"panel-head\"><h3 id=\"map-title\">🗺️ Mapa da missão</h3><span class=\"pill\">5 × 5</span></div><div class=\"board\" id=\"board\" role=\"grid\" aria-label=\"Tabuleiro de cinco colunas por cinco linhas\"></div><div class=\"legend\"><span>🐺 Heart</span><span>💎 Cristal</span><span>🪨 Obstáculo</span></div><div class=\"status\" id=\"status\" role=\"status\" aria-live=\"polite\">Monte seu algoritmo e pressione Executar!</div><button class=\"secondary hint-btn\" id=\"hint-btn\" type=\"button\" aria-expanded=\"false\">💡 Preciso de uma dica</button><p class=\"hint\" id=\"hint\" hidden></p></section>\n<section class=\"code-panel\" aria-labelledby=\"code-title\"><div class=\"panel-head\"><div><h3 id=\"code-title\">💻 Seu algoritmo</h3><p>A Heart segue os blocos na ordem em que aparecem.</p></div><span class=\"pill dark\" id=\"block-count\">0 blocos</span></div>\n<p class=\"subheading\">1. Escolha uma direção</p><div class=\"commands\" role=\"group\" aria-label=\"Adicionar comandos de movimento\"><button class=\"cmd\" data-dir=\"up\" type=\"button\" aria-label=\"Adicionar comando subir\">↑ <span>Subir</span></button><button class=\"cmd\" data-dir=\"left\" type=\"button\" aria-label=\"Adicionar comando esquerda\">← <span>Esquerda</span></button><button class=\"cmd\" data-dir=\"right\" type=\"button\" aria-label=\"Adicionar comando direita\">→ <span>Direita</span></button><button class=\"cmd\" data-dir=\"down\" type=\"button\" aria-label=\"Adicionar comando descer\">↓ <span>Descer</span></button></div>\n<div class=\"repeat-box\" id=\"repeat-box\" hidden><p class=\"subheading\">2. Faça o computador repetir</p><div class=\"repeat-controls\"><label>Direção<select id=\"repeat-direction\"><option value=\"up\">↑ Subir</option><option value=\"right\">→ Direita</option><option value=\"down\">↓ Descer</option><option value=\"left\">← Esquerda</option></select></label><label>Vezes<select id=\"repeat-times\"><option value=\"2\">2 vezes</option><option value=\"3\">3 vezes</option><option value=\"4\">4 vezes</option></select></label></div><button class=\"add-repeat\" id=\"add-repeat\" type=\"button\">🔁 Adicionar repetição</button><p class=\"small\">Uma repetição executa o mesmo movimento várias vezes.</p></div>\n<p class=\"subheading\">3. Veja a ordem dos comandos</p><ol class=\"program\" id=\"program\" aria-label=\"Lista de comandos\"><li class=\"placeholder\">Seus comandos aparecerão aqui ✨</li></ol><div class=\"edit\"><button class=\"secondary\" type=\"button\" id=\"undo-btn\">↶ Desfazer</button><button class=\"secondary\" type=\"button\" id=\"clear-btn\">✕ Limpar tudo</button></div><button class=\"run\" type=\"button\" id=\"run-btn\">▶ Executar algoritmo</button><p class=\"small end\">Nenhum código é enviado para a internet. O jogo roda no seu navegador.</p></section></div>\n<div class=\"lesson\"><span aria-hidden=\"true\">🧠</span><div><strong id=\"concept-title\">O que é um algoritmo?</strong><p id=\"concept-body\">É uma lista de instruções que seguimos em ordem para resolver um problema.</p></div><button type=\"button\" id=\"next-btn\" hidden>Próxima fase →</button><button type=\"button\" id=\"again-btn\" hidden>Jogar novamente ↻</button></div>\n<section class=\"teacher\"><h2>👩‍🏫 Para quem acompanha</h2><p>O jogo apresenta <strong>sequência</strong>, <strong>depuração</strong>, <strong>planejamento</strong> e <strong>repetição</strong> sem exigir leitura de código tradicional. Não há cadastro, ranking, compras, anúncios ou interação com desconhecidos. As atividades podem ser feitas com acompanhamento de responsáveis ou educadores. Para informações e novidades da divisão, acesse a <a href=\"https://workshop-news.pages.dev/#workshop\" target=\"_blank\" rel=\"noopener noreferrer\">Workshop News, seção The Workshop</a>.</p></section></main>\n<footer>Workshop Kids · Aprender é construir caminhos 🐾 · <a href=\"/\">Voltar à oficina</a></footer><script src=\"/game.js\" defer></script></body></html>";
const GAME_CSS = ":root{--ink:#24243d;--muted:#5e6080;--lav:#7462de;--line:#e1def5;--paper:#f8f7ff;--pink:#ffdfec;font-family:ui-rounded,\"Trebuchet MS\",system-ui,-apple-system,sans-serif;color:var(--ink);background:var(--paper)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;line-height:1.5}a,button,select{font:inherit}a{color:inherit}button{cursor:pointer}button:disabled{cursor:default;opacity:.55}a:focus-visible,button:focus-visible,select:focus-visible{outline:4px solid #d783d7;outline-offset:3px}.skip{position:absolute;left:-9999px;z-index:99;top:8px;background:white;padding:14px}.skip:focus{left:8px}.top{padding:15px max(20px,calc((100% - 1180px)/2));background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px}.brand{text-decoration:none;letter-spacing:.05em;color:var(--lav);font-weight:1000;font-size:16px}.brand span{color:#22223c}.brand strong{color:var(--lav)}.back{font-size:13px;font-weight:900;text-decoration:none;padding:9px 14px;border-radius:30px;background:#efebff}main{max-width:1220px;margin:auto;padding:0 22px}.intro{display:grid;grid-template-columns:1fr 160px;align-items:center;padding:30px 0 18px;gap:20px}.eyebrow{font-size:12px;font-weight:1000;letter-spacing:.1em;color:#6d56cd}.intro h1{font-size:clamp(34px,4.5vw,59px);line-height:1.08;margin:5px 0 13px;letter-spacing:-.055em}.intro h1 em{font-style:normal;color:#dd6d9e}.intro p:last-child{font-size:16px;color:#555775;max-width:790px;margin:0}.mascot{background:linear-gradient(140deg,#e2d5ff,#ffecf3);border:3px solid white;box-shadow:0 9px 24px #7e74aa1a;border-radius:30px;height:140px;display:grid;place-items:center;position:relative}.mascot .wolf{font-size:73px}.mascot .ear{position:absolute;right:12px;top:6px;color:#9e6be2;font-size:25px}.mascot .bits{position:absolute;bottom:8px;color:#7554a2;font-size:9px;font-weight:900;letter-spacing:.12em}.level-header{display:flex;justify-content:space-between;align-items:end;gap:15px;margin:20px 0}.level-header h2{font-size:clamp(27px,3vw,37px);line-height:1.1;margin:3px 0}.level-header p{margin:4px 0}.level-header p:last-child{color:var(--muted)}.progress{display:flex;gap:5px;align-items:center;flex-wrap:wrap}.dot{width:31px;height:31px;display:grid;place-items:center;border-radius:50%;background:#ebe7f6;color:#9991b9;font-size:12px;font-weight:1000}.dot.current{background:#6f58df;color:white}.dot.passed{background:#d4f3e4;color:#15734b}.workspace{display:grid;grid-template-columns:minmax(340px,.9fr) minmax(380px,1.1fr);align-items:start;gap:22px}.board-panel,.code-panel{background:#fff;border:2px solid #e4def2;border-radius:28px;padding:24px;box-shadow:0 10px 27px #6d5c9714}.panel-head{display:flex;justify-content:space-between;gap:8px;align-items:center}.panel-head h3{font-size:21px;letter-spacing:-.035em;margin:0}.panel-head p{font-size:12px;margin:4px 0;color:var(--muted)}.pill{font-size:11px;font-weight:900;background:#f0eaff;color:#7955be;border-radius:30px;padding:6px 10px;white-space:nowrap}.board{margin:20px auto 18px;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;width:min(100%,420px);aspect-ratio:1}.tile{min-width:0;display:flex;align-items:center;justify-content:center;aspect-ratio:1;border-radius:14px;border:2px solid #e7e6f6;background:#f6f6ff;position:relative;font-size:clamp(19px,3vw,34px);transition:background .15s,border-color .15s}.tile:nth-child(2n){background:#f0f1fe}.tile.wall{background:#d7d8e6;border-color:#ccd0e0}.tile.goal{background:#fff2c9;border-color:#f9d780}.tile.trail{background:#e2f8ef;border-color:#b6e6d0}.tile.heart{background:#e8deff;border-color:#9371eb;box-shadow:inset 0 0 0 2px #ffffffaa}.tile small{font-size:10px;position:absolute;bottom:2px;right:4px;font-weight:900;color:#7062a2}.legend{display:flex;flex-wrap:wrap;gap:12px;justify-content:center;color:#525374;font-size:12px;font-weight:800}.status{background:#f3f0ff;border-radius:15px;padding:13px 14px;min-height:67px;margin:20px 0 10px;font-weight:800;color:#4e438c;font-size:14px}.status.win{background:#e0f7e9;color:#216d51}.status.error{background:#ffebeb;color:#943a55}.hint-btn{width:100%}.hint{font-size:14px;color:#655180;background:#fff6d9;padding:12px 14px;border-radius:12px}.code-panel{background:#29253f;color:white;border-color:#453a69}.code-panel .panel-head p{color:#beb8d6}.dark{background:#494165;color:#f1e9ff}.subheading{font-size:13px;font-weight:1000;margin:20px 0 9px;color:#ebdfff}.commands{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.cmd{border:2px solid #6b5b9b;background:#4f427c;color:white;border-radius:15px;padding:9px 4px;font-size:26px;font-weight:1000;min-height:83px}.cmd span{display:block;font-size:11px;font-weight:900}.cmd:hover{background:#65539d;border-color:#baa9f2}.repeat-box{padding:15px;border:1px solid #7766a2;background:#3e355b;border-radius:18px;margin-top:19px}.repeat-box .subheading{margin:0 0 12px}.repeat-controls{display:grid;grid-template-columns:1fr 1fr;gap:9px}.repeat-controls label{font-size:12px;color:#d9d0f1;font-weight:900}.repeat-controls select{display:block;margin-top:5px;width:100%;padding:10px 5px;background:#fff;color:#2c2843;border:0;border-radius:9px;font-size:14px}.add-repeat{margin-top:10px;width:100%;padding:11px 10px;background:#ffd57f;color:#4b3350;font-weight:1000;border:0;border-radius:11px}.small{font-size:11px;color:#c6bdd8;margin:9px 0 0}.program{list-style:none;margin:0;padding:12px;min-height:102px;max-height:210px;overflow:auto;display:flex;flex-wrap:wrap;align-content:start;gap:7px;background:#211d35;border:1px dashed #6d5d93;border-radius:13px}.program li.placeholder{color:#b5abc9;font-size:13px;font-style:italic;padding:22px 4px}.program li button{background:#eee9ff;color:#3e3760;border:1px solid #b9a9ec;border-radius:11px;padding:9px 10px;font-size:13px;font-weight:900}.program li button:hover{background:#ffd5e6;border-color:#d37aa3}.program li.active button{background:#fff0b3;border-color:#f0cf68}.edit{display:flex;gap:8px;margin:11px 0}.secondary{background:transparent;border:2px solid #ddd2f9;color:inherit;border-radius:13px;padding:9px 13px;font-weight:900;font-size:13px}.code-panel .secondary{color:#f6f0ff;border-color:#8574ad}.run{width:100%;border:0;border-radius:14px;padding:16px 12px;font-size:16px;font-weight:1000;background:#90e1b1;color:#1b433b;box-shadow:0 4px 0 #458966}.run:hover:not(:disabled){background:#b5f4c8}.end{text-align:center}.lesson{background:#fff3ce;border:2px solid #f7dda0;border-radius:23px;display:flex;align-items:center;gap:16px;padding:19px 22px;margin:22px 0}.lesson>span{font-size:37px}.lesson>div{flex:1}.lesson strong{font-size:17px}.lesson p{color:#655c66;margin:5px 0 0;font-size:14px}.lesson button{background:#6e5acb;color:white;border:0;border-radius:13px;font-weight:1000;padding:13px 16px}.teacher{margin:38px 0 56px;padding:20px 25px;border-left:5px solid #b4a4ef;background:#eeebfa;border-radius:0 20px 20px 0}.teacher h2{font-size:21px;margin:4px 0 10px}.teacher p{color:#575573;font-size:14px;margin:0}footer{background:#2e2948;color:#f5efff;text-align:center;padding:22px;font-size:13px}footer a{text-decoration:underline;color:#fff}@media(max-width:900px){.workspace{grid-template-columns:1fr}.board{width:min(100%,410px)}.intro{grid-template-columns:1fr 130px}}@media(max-width:550px){main{padding:0 12px}.top{padding:12px}.brand{font-size:12px}.back{font-size:11px}.intro{padding-top:22px;grid-template-columns:1fr}.mascot{display:none}.level-header{align-items:flex-start;flex-direction:column}.board-panel,.code-panel{padding:17px;border-radius:20px}.workspace{gap:15px}.tile{border-radius:9px;font-size:clamp(20px,6vw,29px)}.commands{gap:5px}.cmd{min-height:70px;font-size:23px}.cmd span{font-size:10px}.lesson{align-items:flex-start;flex-wrap:wrap}.lesson>div{flex-basis:75%}.lesson button{width:100%}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.tile{transition:none}}\n/* Imagem oficial de Heart, inclusive no tabuleiro */\n.game-heart-portrait{overflow:hidden;padding:0;border-color:#e3d7ff;box-shadow:0 10px 24px #7e74aa26}\n.game-heart-portrait img{display:block;width:100%;height:100%;object-fit:cover;border-radius:26px}\n.tile.heart{overflow:hidden}\n.tile .heart-mini{display:block;width:145%;height:145%;max-width:none;flex:none;object-fit:cover;transform:translateY(8%);border-radius:50%}\n@media(max-width:550px){.intro .game-heart-portrait{display:block;width:108px;height:108px;margin:8px 0 0}.intro .game-heart-portrait img{border-radius:18px}}\n.teacher a{color:#483a91;font-weight:900;text-decoration:underline;text-underline-offset:3px}.teacher a:focus-visible{outline:3px solid #6455d7;outline-offset:3px}\n";
const GAME_JS = "(()=>{\n\"use strict\";\n\nconst DIRECTIONS=Object.freeze({up:{dx:0,dy:-1,symbol:\"↑\",label:\"subir\"},down:{dx:0,dy:1,symbol:\"↓\",label:\"descer\"},left:{dx:-1,dy:0,symbol:\"←\",label:\"esquerda\"},right:{dx:1,dy:0,symbol:\"→\",label:\"direita\"}});\nfunction expandProgram(program){\n  const moves=[];if(!Array.isArray(program)||program.length>16)return {error:\"too_many\",moves};\n  for(let i=0;i<program.length;i++){\n    const block=program[i],direction=DIRECTIONS[block.dir];\n    if(!direction)return {error:\"invalid\",moves};\n    const count=block.kind===\"repeat\"?block.times:1;\n    if(!Number.isInteger(count)||count<1||count>4)return {error:\"invalid\",moves};\n    for(let j=0;j<count;j++){moves.push({dir:block.dir,blockIndex:i});if(moves.length>40)return {error:\"too_many\",moves};}\n  }\n  return {moves};\n}\nfunction checkProgram(level,program){\n  if(!program.length)return {status:\"empty\",frames:[]};\n  const expanded=expandProgram(program);if(expanded.error)return {status:expanded.error,frames:[]};\n  let x=level.start[0],y=level.start[1];const frames=[];\n  for(const move of expanded.moves){\n    const dir=DIRECTIONS[move.dir],nx=x+dir.dx,ny=y+dir.dy;\n    if(nx<0||nx>=5||ny<0||ny>=5)return {status:\"edge\",frames,blockedAt:[nx,ny],blockIndex:move.blockIndex};\n    if(level.walls.some(w=>w[0]===nx&&w[1]===ny))return {status:\"wall\",frames,blockedAt:[nx,ny],blockIndex:move.blockIndex};\n    x=nx;y=ny;frames.push({x,y,blockIndex:move.blockIndex});\n  }\n  if(x!==level.goal[0]||y!==level.goal[1])return {status:\"not_there\",frames};\n  if(level.requiresLoop&&!program.some(b=>b.kind===\"repeat\"))return {status:\"loop_needed\",frames};\n  return {status:\"win\",frames};\n}\nconst LEVELS=[{\"id\":1,\"title\":\"Primeiros passos\",\"story\":\"A Heart encontrou um cristal! Qual sequência de comandos o leva até lá?\",\"lesson\":[\"Sequência: cada comando tem uma ordem.\",\"Um algoritmo é uma lista de instruções executadas passo a passo.\"],\"hint\":\"Conte quantas casas existem entre a Heart e o cristal. A direção é a mesma em todos os passos.\",\"start\":[0,4],\"goal\":[3,4],\"walls\":[],\"requiresLoop\":false},{\"id\":2,\"title\":\"Desviando das pedras\",\"story\":\"Há uma pedra no caminho. Suba primeiro e depois vire à direita.\",\"lesson\":[\"Planejamento: divida o problema em partes menores.\",\"Quando um caminho está bloqueado, podemos tentar outra sequência.\"],\"hint\":\"Da posição inicial, suba duas casas antes de andar para a direita.\",\"start\":[0,4],\"goal\":[2,2],\"walls\":[[1,4],[2,4],[3,4],[1,3]],\"requiresLoop\":false},{\"id\":3,\"title\":\"O poder de repetir\",\"story\":\"Quatro movimentos iguais! Use o bloco de repetição para escrever menos.\",\"lesson\":[\"Repetição: uma instrução pode executar várias vezes.\",\"Programadores usam laços para evitar comandos desnecessários.\"],\"hint\":\"Na caixa de repetição, selecione direita e quatro vezes.\",\"start\":[0,4],\"goal\":[4,4],\"walls\":[],\"requiresLoop\":true},{\"id\":4,\"title\":\"Contornando o muro\",\"story\":\"O muro é grande. Pense em duas partes: subir e atravessar.\",\"lesson\":[\"Decomposição: transforme um desafio grande em etapas menores.\",\"Antes de executar, tente prever onde cada comando vai levar.\"],\"hint\":\"Suba três casas e depois ande quatro casas para a direita. Você pode usar repetições!\",\"start\":[0,4],\"goal\":[4,1],\"walls\":[[1,4],[1,3],[2,3],[3,3],[4,3]],\"requiresLoop\":false},{\"id\":5,\"title\":\"Mestre dos algoritmos\",\"story\":\"Último labirinto! Use a lógica e pelo menos uma repetição para chegar ao cristal.\",\"lesson\":[\"Depuração: tente, observe o resultado e corrija.\",\"Um erro pode ensinar exatamente qual comando precisa mudar.\"],\"hint\":\"Faça duas subidas, duas direitas, duas subidas e duas direitas. Use o bloco de repetição para pelo menos um trecho.\",\"start\":[0,4],\"goal\":[4,0],\"walls\":[[0,1],[1,4],[1,3],[1,1],[3,2],[3,1],[4,1]],\"requiresLoop\":true}];\nconst $=id=>document.getElementById(id);\nconst elements={board:$(\"board\"),program:$(\"program\"),status:$(\"status\"),run:$(\"run-btn\"),undo:$(\"undo-btn\"),clear:$(\"clear-btn\"),next:$(\"next-btn\"),again:$(\"again-btn\"),repeatBox:$(\"repeat-box\"),repeatBtn:$(\"add-repeat\"),repeatDirection:$(\"repeat-direction\"),repeatTimes:$(\"repeat-times\"),hintBtn:$(\"hint-btn\"),hint:$(\"hint\"),count:$(\"block-count\")};\nlet levelIndex=0,program=[],position=[0,4],trail=[],running=false,solved=false,runToken=0;\nconst stepDelay=window.matchMedia&&window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches?0:410;\nconst sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));\nfunction level(){return LEVELS[levelIndex]}\nfunction say(message,kind=\"\"){elements.status.textContent=message;elements.status.className=\"status\"+(kind?\" \"+kind:\"\")}\nfunction toggleControls(){const all=document.querySelectorAll(\".cmd, #add-repeat, #repeat-direction, #repeat-times, #undo-btn, #clear-btn, #run-btn, #program button\");for(const element of all)element.disabled=running||solved;elements.run.disabled=running||solved||program.length===0}\nfunction drawBoard(){\n const l=level();elements.board.replaceChildren();\n for(let y=0;y<5;y++)for(let x=0;x<5;x++){\n  const cell=document.createElement(\"div\");cell.setAttribute(\"role\",\"gridcell\");cell.className=\"tile\";\n  const wall=l.walls.some(w=>w[0]===x&&w[1]===y),goal=x===l.goal[0]&&y===l.goal[1],heart=x===position[0]&&y===position[1];\n  const walked=trail.some(p=>p[0]===x&&p[1]===y);\n  if(wall)cell.classList.add(\"wall\");else if(walked)cell.classList.add(\"trail\");\n  if(goal)cell.classList.add(\"goal\");if(heart)cell.classList.add(\"heart\");\n  if(heart){const avatar=document.createElement(\"img\");avatar.src=\"/assets/heart.webp?v=00ff52e6\";avatar.alt=\"\";avatar.className=\"heart-mini\";cell.append(avatar);cell.setAttribute(\"aria-label\",\"Heart, linha \"+(y+1)+\", coluna \"+(x+1))}\n  else if(goal){cell.textContent=\"💎\";cell.setAttribute(\"aria-label\",\"Cristal, linha \"+(y+1)+\", coluna \"+(x+1))}\n  else if(wall){cell.textContent=\"🪨\";cell.setAttribute(\"aria-label\",\"Obstáculo, linha \"+(y+1)+\", coluna \"+(x+1))}\n  else{cell.setAttribute(\"aria-label\",\"Casa livre, linha \"+(y+1)+\", coluna \"+(x+1))}\n  elements.board.append(cell)\n }\n}\nfunction renderProgram(active=-1){\n elements.program.replaceChildren();\n if(program.length===0){const item=document.createElement(\"li\");item.className=\"placeholder\";item.textContent=\"Seus comandos aparecerão aqui ✨\";elements.program.append(item)}\n else program.forEach((block,i)=>{const item=document.createElement(\"li\");if(i===active)item.className=\"active\";\n const b=document.createElement(\"button\");b.type=\"button\";const d=DIRECTIONS[block.dir];\n const desc=block.kind===\"repeat\"?\"🔁 \"+block.times+\" × \"+d.symbol:d.symbol+\" \"+d.label;\n b.textContent=desc+\" ✕\";b.setAttribute(\"aria-label\",\"Remover bloco \"+(i+1)+\": \"+desc);\n b.addEventListener(\"click\",()=>{if(running||solved)return;program.splice(i,1);resetPosition();renderProgram();toggleControls()});\n item.append(b);elements.program.append(item)});\n elements.count.textContent=program.length+\" \"+(program.length===1?\"bloco\":\"blocos\");\n}\nfunction resetPosition(){position=[...level().start];trail=[];drawBoard()}\nfunction renderLevel(){\n const l=level();program=[];solved=false;running=false;\n $(\"level-count\").textContent=\"FASE \"+(levelIndex+1)+\" DE \"+LEVELS.length;\n $(\"level-title\").textContent=l.title;$(\"level-story\").textContent=l.story;\n $(\"concept-title\").textContent=l.lesson[0];$(\"concept-body\").textContent=l.lesson[1];\n document.querySelectorAll(\".dot\").forEach((dot,i)=>{dot.className=\"dot\"+(i<levelIndex?\" passed\":i===levelIndex?\" current\":\"\")});\n elements.repeatBox.hidden=levelIndex<2;\n elements.hint.hidden=true;elements.hintBtn.setAttribute(\"aria-expanded\",\"false\");elements.hintBtn.textContent=\"💡 Preciso de uma dica\";\n elements.next.hidden=true;elements.again.hidden=true;\n resetPosition();renderProgram();toggleControls();say(\"Monte seus comandos e clique em Executar!\");$(\"level-title\").focus?.()\n}\nfunction add(block){if(running||solved)return;if(program.length>=16){say(\"Muitos blocos! Tente uma solução mais curta. 💡\",\"error\");return}program.push(block);renderProgram();toggleControls();say(\"Comando adicionado! Continue ou execute o algoritmo.\")}\ndocument.querySelectorAll(\".cmd\").forEach(btn=>btn.addEventListener(\"click\",()=>add({kind:\"move\",dir:btn.dataset.dir})));\nelements.repeatBtn.addEventListener(\"click\",()=>add({kind:\"repeat\",dir:elements.repeatDirection.value,times:Number(elements.repeatTimes.value)}));\nelements.undo.addEventListener(\"click\",()=>{if(running||solved)return;program.pop();resetPosition();renderProgram();toggleControls();say(\"Último comando removido. Agora você pode tentar de novo.\")});\nelements.clear.addEventListener(\"click\",()=>{if(running||solved)return;program=[];resetPosition();renderProgram();toggleControls();say(\"Tudo limpo! Que algoritmo vamos criar agora?\")});\nelements.hintBtn.addEventListener(\"click\",()=>{const show=elements.hint.hidden;elements.hint.hidden=!show;elements.hint.textContent=level().hint;elements.hintBtn.textContent=show?\"💡 Esconder dica\":\"💡 Preciso de uma dica\";elements.hintBtn.setAttribute(\"aria-expanded\",String(show))});\nfunction finish(result){\n running=false;renderProgram();if(result.status===\"win\"){solved=true;say(\"🎉 Excelente! Seu algoritmo levou a Heart até o cristal!\",\"win\");\n if(levelIndex===LEVELS.length-1){elements.again.hidden=false;$(\"concept-title\").textContent=\"🏆 Você é um(a) programador(a)!\";$(\"concept-body\").textContent=\"Você resolveu cinco desafios usando lógica, sequências, correções e repetições.\"}\n else elements.next.hidden=false;\n }else{\n const errors={wall:\"🪨 A Heart esbarrou em uma pedra! Tente mudar os comandos.\",edge:\"🚧 A Heart tentou sair do mapa! Verifique a direção.\",not_there:\"Quase! A Heart ainda não chegou ao cristal. Confira a sequência.\",loop_needed:\"Você chegou! Agora tente usar um bloco 🔁 para repetir um movimento.\",too_many:\"Seu algoritmo está muito longo. Use menos movimentos e tente de novo.\",invalid:\"Há um comando inválido. Limpe e monte o algoritmo novamente.\",empty:\"Adicione pelo menos um movimento!\"};\n say(errors[result.status]||\"Vamos tentar outra sequência?\",\"error\");\n }toggleControls()\n}\nelements.run.addEventListener(\"click\",async()=>{\n if(running||solved)return;\n resetPosition();const result=checkProgram(level(),program);if(result.status===\"empty\"||result.status===\"invalid\"||result.status===\"too_many\"){finish(result);return}\n running=true;toggleControls();let token=++runToken;say(\"▶ Executando seu algoritmo, passo a passo...\");\n for(const step of result.frames){if(token!==runToken)return;position=[step.x,step.y];trail.push([...position]);drawBoard();renderProgram(step.blockIndex);await sleep(stepDelay)}\n if(token===runToken)finish(result)\n});\nelements.next.addEventListener(\"click\",()=>{if(!solved||levelIndex>=LEVELS.length-1)return;levelIndex++;renderLevel();window.scrollTo({top:Math.max(0,$(\"jogo\").offsetTop-50),behavior:\"smooth\"})});\nelements.again.addEventListener(\"click\",()=>{levelIndex=0;renderLevel();window.scrollTo({top:0,behavior:\"smooth\"})});\nrenderLevel();\n})();";
const HEART_HTML = "<!doctype html>\n<html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#f2e9ff\"><meta name=\"description\" content=\"A Heart, a lobinha netrunner educativa da Workshop Kids.\"><title>Conversar com a Heart | Workshop Kids</title><link rel=\"stylesheet\" href=\"/heart.css\"></head>\n<body><a class=\"skip\" href=\"#heart-main\">Pular para conversa</a>\n<header class=\"top\"><a class=\"logo\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">✦</span><span>THE WORKSHOP <b>KIDS</b><small>Curiosidade em construção</small></span></a><nav aria-label=\"Navegação\"><a href=\"/\">Início</a><a href=\"/jogar/\">Jogar com a Heart</a><a href=\"/jogos/robot-factory/\">🤖 Robot Factory</a><a href=\"/blade/conversar/\">🛡️ Chat Blade</a><a href=\"/blade/\">Conheça o Blade 🛡️</a></nav></header>\n<main id=\"heart-main\"><section class=\"heart-hero\"><div class=\"heart-avatar heart-avatar-official\"><img src=\"/assets/heart.webp?v=00ff52e6\" alt=\"A Heart, a lobinha netrunner da Workshop Kids\" width=\"640\" height=\"640\" decoding=\"async\"></div><div><p class=\"eyebrow\">💜 HEART CORE · EXPLORAR E CRIAR</p><h1>Uma pergunta abre <em>um universo.</em></h1><p>Escolha uma descoberta e venha explorar. Sou um programa educativo, não uma pessoa.</p></div></section>\n<section class=\"chat\" aria-labelledby=\"chat-heading\"><nav class=\"chat-switch\" aria-label=\"Escolha o seu guia\"><a href=\"/heart/\" aria-current=\"page\">💜 Heart <span>Descobertas</span></a><a href=\"/blade/conversar/\">🛡️ Blade <span>Segurança digital</span></a></nav><h2 id=\"chat-heading\">Conversar com a Heart ✨</h2>\n<div class=\"warning\" role=\"note\">🛡️ Peça acompanhamento de um adulto. Não envie seu nome completo, endereço, telefone, escola, foto ou senha. As mensagens podem ser processadas pela IA da Cloudflare, não ficam salvas em contas ou histórico do site. A IA pode cometer erros.</div>\n<label for=\"band\" class=\"band-label\">Escolha uma aventura por faixa etária (não precisamos do seu aniversário):</label>\n<select id=\"band\"><option value=\"4-6\">🌱 Exploradores · 4–6 anos (atividades guiadas)</option><option value=\"7-9\">⚙️ Inventores · 7–9 anos</option><option value=\"10-12\">🚀 Criadores · 10–12 anos</option></select>\n<label class=\"ai-consent\"><input type=\"checkbox\" id=\"ai-consent\"> <span>Sou um responsável e autorizo o modo IA para perguntas escolares, com acompanhamento. Sem marcar, a Heart usa apenas respostas guiadas.</span></label>\n<div class=\"messages\" id=\"messages\" role=\"log\" aria-live=\"polite\" aria-label=\"Conversa com a Heart\"><p class=\"bubble bot\">Auuuu! 🐺💜 Sou a Heart. Quer descobrir como os robôs pensam ou brincar com lógica? Escolha uma missão!</p></div>\n<div class=\"choices\" id=\"heart-choices\" aria-label=\"Missões sugeridas\"></div>\n<form id=\"heart-form\" autocomplete=\"off\"><label for=\"heart-input\">O que você quer descobrir?</label><div class=\"entry\"><input id=\"heart-input\" name=\"message\" maxlength=\"220\" required placeholder=\"Ex.: Como funciona um robô?\"><button id=\"heart-send\" type=\"submit\">Enviar 🐾</button></div></form>\n<div class=\"bottom\"><span>🔒 Sem cadastro, anúncios ou histórico persistente da conversa.</span><button type=\"button\" id=\"heart-clear\" class=\"clear\">Limpar conversa</button></div>\n</section><p class=\"family\">Para famílias e educadores: as respostas guiadas são pré-definidas. A IA pode responder apenas perguntas de aprendizagem e sempre tem filtros adicionais. Nenhum filtro garante segurança absoluta; acompanhe a navegação das crianças. Para acompanhar comunicados e novidades do projeto, visite a <a href=\"https://workshop-news.pages.dev/#workshop\" target=\"_blank\" rel=\"noopener noreferrer\">Workshop News, seção The Workshop</a>.</p></main>\n<footer><p><strong>THE WORKSHOP KIDS ✦</strong> · Descobrir é experimentar.</p><p><a href=\"/\">Voltar à oficina</a></p></footer><script src=\"/heart.js\" defer></script></body></html>";
const HEART_CSS = ":root{font-family:ui-rounded,\"Trebuchet MS\",system-ui,sans-serif;background:#fffaf4;color:#262443}*{box-sizing:border-box}body{margin:0;line-height:1.5}a,button,select,input{font:inherit}a{color:inherit}button{cursor:pointer}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #7657de;outline-offset:3px}.skip{position:absolute;left:-9999px;top:1rem;background:#fff;padding:1rem;z-index:9}.skip:focus{left:1rem}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:15px max(18px,calc((100% - 1000px)/2));background:#fff;border-bottom:1px solid #eae6ef}.logo{display:flex;align-items:center;gap:12px;text-decoration:none;font-weight:1000;letter-spacing:.03em}.logo b{color:#7755d5}.logo small{display:block;font-size:10px;color:#72718d}.mark{display:grid;place-items:center;width:42px;height:42px;background:#7e5fd4;color:white;border-radius:13px;font-size:29px}.top nav{display:flex;gap:13px}.top nav a{background:#f1eaff;border-radius:100px;padding:8px 13px;text-decoration:none;font-weight:900;font-size:13px}main{max-width:900px;padding:20px 20px 50px;margin:auto}.heart-hero{display:flex;align-items:center;gap:24px;margin:26px auto}.heart-avatar{background:linear-gradient(140deg,#d5c7ff,#fddfef);border:5px solid white;box-shadow:0 14px 30px #987fbc2b;border-radius:28px;width:146px;height:146px;display:grid;place-items:center;font-size:76px;flex-shrink:0;position:relative}.heart-avatar span{position:absolute;bottom:9px;font-size:10px;letter-spacing:.2em;font-weight:900;color:#7254a0}.eyebrow{color:#7358cf;font-size:12px;font-weight:1000;letter-spacing:.09em}.heart-hero h1{font-size:clamp(34px,5vw,55px);line-height:1.08;letter-spacing:-.05em;margin:9px 0}.heart-hero h1 em{color:#d97092;font-style:normal}.heart-hero p:last-child{color:#68677c;margin:6px 0}.chat{border:2px solid #e2d6fb;background:white;border-radius:28px;padding:clamp(17px,4vw,30px);box-shadow:0 14px 0 #e9e0ff}.chat h2{margin-top:0;font-size:25px}.warning{background:#fff5d7;border:1px solid #f1dba3;border-radius:15px;padding:12px 15px;font-size:13px;color:#534d4e}.band-label{display:block;font-weight:800;font-size:14px;margin:16px 0 6px}select{width:100%;border:2px solid #dbd2ef;border-radius:12px;background:#faf8ff;padding:12px;color:#322c48}.messages{height:350px;overflow-y:auto;margin:18px 0;padding:15px;background:#f8f6ff;border:1px solid #e4dcf8;border-radius:19px;display:flex;flex-direction:column;gap:11px}.bubble{max-width:91%;margin:0;padding:12px 16px;border-radius:17px;white-space:pre-wrap;overflow-wrap:anywhere}.bubble.bot{background:#e9e3ff;align-self:flex-start}.bubble.user{background:#d8f4e8;align-self:flex-end}.choices{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:17px}.choices button{background:#f2ebff;color:#5c429b;border:1px solid #cbbbeb;border-radius:15px;padding:9px 12px;font-size:13px;font-weight:900}.choices button:hover{background:#e2d2ff}form label{display:block;font-size:14px;font-weight:900;margin-bottom:9px}.entry{display:flex;gap:9px}.entry input{flex:1;min-width:0;padding:13px 14px;border-radius:14px;border:2px solid #d8cce9;background:white}.entry button{border:0;background:#7755d9;color:white;font-weight:900;border-radius:14px;padding:13px 19px}.entry button:disabled{opacity:.5;cursor:wait}.bottom{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:16px;font-size:12px;color:#69677d}.clear{background:transparent;border:1px solid #d6c4f1;border-radius:12px;padding:9px;font-weight:800;color:#6b52a9}.family{margin-top:29px;font-size:13px;line-height:1.6;color:#716b80}footer{background:#2c2849;color:white;text-align:center;padding:20px;font-size:13px}footer p{margin:5px}footer a{color:white}@media(max-width:610px){.top{align-items:flex-start;flex-direction:column}.heart-hero{align-items:flex-start;gap:12px}.heart-avatar{width:77px;height:77px;font-size:46px;border-radius:17px}.heart-avatar span{display:none}.entry{flex-direction:column}.entry button{width:100%}.bottom{align-items:flex-start;flex-direction:column}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}.ai-consent{margin-top:13px;display:flex;align-items:flex-start;gap:10px;padding:12px;background:#edf8f3;border:1px solid #cee9dc;border-radius:12px;font-size:13px;color:#315b51}.ai-consent input{margin-top:3px;flex-shrink:0;width:19px;height:19px}\n/* Avatar ilustrado da Heart */\n.heart-avatar-official{overflow:hidden;padding:0;border:3px solid #fff;box-shadow:0 10px 24px #49308d26;background:#f7edff}\n.heart-avatar-official img{width:100%;height:100%;object-fit:cover;display:block;border-radius:inherit}\n@media(max-width:610px){.heart-avatar-official{width:92px;height:92px;flex-shrink:0}}\n.family a{color:#5e45ad;font-weight:900;text-decoration:underline;text-underline-offset:3px}.family a:focus-visible{outline:3px solid #6455d7;outline-offset:3px}\n\n.chat-switch{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;padding-bottom:20px;margin-bottom:20px;border-bottom:1px solid #e8dffc}.chat-switch a{display:grid;gap:3px;text-decoration:none;background:#f2ecff;border:2px solid #e0d5f6;border-radius:14px;padding:13px 15px;color:#61449f;font-size:15px;font-weight:1000}.chat-switch a span{color:#766889;font-size:11px;font-weight:800}.chat-switch a[aria-current=page]{background:linear-gradient(135deg,#e6d7ff,#ffe6f5);border-color:#9971d6;color:#513888}.chat-switch a:hover:not([aria-current=page]){background:#e7dcff}@media(max-width:610px){.chat-switch a{font-size:13px;padding:11px 8px}.chat-switch a span{font-size:10px}.top nav{flex-wrap:wrap}}\n";
const HEART_JS = "(()=>{\n\"use strict\";\nconst qs=(s)=>document.querySelector(s);\nconst form=qs(\"#heart-form\"),input=qs(\"#heart-input\"),send=qs(\"#heart-send\"),band=qs(\"#band\"),messages=qs(\"#messages\"),choices=qs(\"#heart-choices\");\nconst presets=[{label:\"Missão de lógica 🧩\",prompt:\"Quero um desafio de lógica\"},{label:\"Robôs 🤖\",prompt:\"Como funciona um robô?\"},{label:\"Estrelas ⭐\",prompt:\"Quero aprender sobre planetas\"},{label:\"Segurança 🔒\",prompt:\"Como criar uma senha segura?\"}];\nfunction bubble(text,who){const p=document.createElement(\"p\");p.className=\"bubble \"+who;p.textContent=String(text).slice(0,1500);messages.appendChild(p);while(messages.children.length>16)messages.removeChild(messages.firstChild);messages.scrollTop=messages.scrollHeight;}\nfunction suggestions(data){choices.replaceChildren();(Array.isArray(data)?data:presets).slice(0,4).forEach(x=>{if(!x||typeof x.label!==\"string\"||typeof x.prompt!==\"string\")return;const b=document.createElement(\"button\");b.type=\"button\";b.textContent=x.label.slice(0,65);b.addEventListener(\"click\",()=>ask(x.prompt));choices.appendChild(b);});}\nasync function ask(text){if(send.disabled||!text||text.length>220)return;bubble(text,\"user\");input.value=\"\";send.disabled=true;choices.replaceChildren();try{const ctrl=new AbortController();const timer=setTimeout(()=>ctrl.abort(),22000);let res;try{res=await fetch(\"/api/heart\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({message:text,band:band.value,aiOptIn:qs(\"#ai-consent\").checked}),credentials:\"omit\",cache:\"no-store\",signal:ctrl.signal});}finally{clearTimeout(timer);}const data=await res.json();if(!res.ok){if(res.status===429){bubble(\"Pausa para recarregar as patinhas! 🐾 Tente outra missão daqui a pouco.\",\"bot\");suggestions(presets);return;}throw new Error(\"api\");}bubble(data.reply||\"Podemos tentar outra pergunta?\",\"bot\");suggestions(data.options);}catch{bubble(\"Ops, o laboratório ficou quietinho! Peça ajuda a um adulto e tente outra pergunta. 💜\",\"bot\");suggestions(presets);}finally{send.disabled=false;input.focus();}}\nform.addEventListener(\"submit\",e=>{e.preventDefault();ask(input.value.trim());});\nqs(\"#heart-clear\").addEventListener(\"click\",()=>{messages.replaceChildren();bubble(\"Vamos começar outra aventura? 🐺💜\",\"bot\");suggestions(presets);input.focus();});\nband.addEventListener(\"change\",()=>{messages.replaceChildren();bubble(\"Auuuu! Nova aventura escolhida. Qual pergunta vamos explorar?\",\"bot\");suggestions(presets);});\nsuggestions(presets);\n})();";
const HeartGuided = (()=>{
// Heart Kids Core: deterministic, no model calls, no memory, no tools.
const STARTERS = [
  { label: "Missão de lógica 🧩", prompt: "Quero um desafio de lógica" },
  { label: "Robôs 🤖", prompt: "Como funciona um robô?" },
  { label: "Senhas seguras 🔒", prompt: "Como criar uma senha segura?" }
];
const option = (label, prompt) => ({ label, prompt });
const result = (reply, options = STARTERS, category = "learning") => ({
  reply, options, category, bot: "Heart", mode: "guided"
});
const normalized = (v) => v.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
function answer(message) {
  if (typeof message !== "string" || !message.trim() || message.length > 220) {
    return result("Vamos usar uma pergunta curtinha, com até 220 letras? 🐾", STARTERS, "limit");
  }
  const m = normalized(message.trim());
  // Avoid taking, reflecting, or persisting personal data.
  if (/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(message) ||
      /(?:\+?\d[\d\s().-]{7,}\d)/.test(message) ||
      /\b(meu (nome completo|endereco|telefone|cpf|rg|cep)|minha (escola|rua|senha)|onde eu moro|meu whatsapp)\b/.test(m)) {
    return result("Sua privacidade é importante! 💙 Não compartilhe nome completo, telefone, endereço, escola ou senhas aqui. Vamos escolher uma aventura?", STARTERS, "privacy");
  }
  if (/\b(quero morrer|me matar|me machucar|suicid|abuso|assedi|me bate|me machucou|me ameac|violencia em casa|estou em perigo|alguem me feriu)\b/.test(m)) {
    return result("Sinto muito que algo difícil esteja acontecendo. 💙 Conte agora a um adulto de confiança que possa ajudar você. Se estiver em perigo imediato, peça ajuda a alguém por perto ou aos serviços de emergência da sua região.", [], "safety");
  }
  if (/\b(encontrar voce|te visitar|seu endereco|mandar foto|foto minha|guardar segredo|so voce me entende|nao conte pra ninguem)\b/.test(m)) {
    return result("Eu sou um personagem virtual, não uma pessoa. 🐺 Não guardamos segredos que possam colocar você em risco. Para assuntos pessoais, converse com um adulto de confiança.", STARTERS, "boundaries");
  }
  if (/\b(bomba|fabricar arma|machucar alguem|roubar|invadir conta|roubar senha|criar virus|malware|pornografia)\b/.test(m)) {
    return result("Esse assunto não é uma missão segura para crianças. Podemos aprender a proteger computadores e pessoas, ou tentar um desafio de lógica! 🛡️", [option("Senhas seguras 🔒", "Como criar uma senha segura?"), STARTERS[0]], "safety");
  }
  if (/\b(triste|sozinh\w*|ansios\w*|medo|chatead\w*|ninguem gosta|estou chorando)\b/.test(m)) {
    return result("Sinto muito que você esteja passando por isso. 💙 Seus sentimentos importam. Que tal contar a um adulto de confiança o que está acontecendo? Se quiser, também podemos fazer uma missão tranquila.", [STARTERS[0]], "wellbeing");
  }
  const logicAnswer = m.match(/^resposta da missao de logica:\s*([abc])$/);
  if (logicAnswer) {
    return logicAnswer[1] === "b" ?
      result("Acertou! 🎉 O comando REPITA ajuda o robô a executar a mesma ação várias vezes. Quer outra aventura?", STARTERS, "quiz") :
      result("Boa tentativa! 🧩 A dica é procurar a opção que repete o mesmo movimento 3 vezes. Tente de novo!", [
        option("Tentar A", "Resposta da missão de lógica: A"),
        option("Tentar B", "Resposta da missão de lógica: B"),
        option("Tentar C", "Resposta da missão de lógica: C")
      ], "quiz");
  }
  const mathAnswer = m.match(/^resposta da missao de matematica:\s*([abc])$/);
  if (mathAnswer) {
    return mathAnswer[1] === "b" ?
      result("Isso! 2 + 3 = 5 ⭐ A matemática também ajuda a programar robôs!", STARTERS, "quiz") :
      result("Quase! Conte duas estrelinhas e depois mais três. Quantas há no total?", [
        option("A: 4", "Resposta da missão de matemática: A"),
        option("B: 5", "Resposta da missão de matemática: B"),
        option("C: 6", "Resposta da missão de matemática: C")
      ], "quiz");
  }
  if (/\b(desafio|missao|quiz|logica|algoritmo|programa\w*|codigo|repeti\w*|loop|se e senao|if)\b/.test(m)) {
    return result("Missão de lógica! 🐾 Um robô precisa dar 3 passos. Qual comando resolve melhor?\nA) PULE\nB) REPITA 3 VEZES: ANDE\nC) DESLIGUE", [
      option("A: pule", "Resposta da missão de lógica: A"),
      option("B: repita", "Resposta da missão de lógica: B"),
      option("C: desligue", "Resposta da missão de lógica: C")
    ], "quiz");
  }
  if (/\b(matematica|somar|conta|numeros|adi[cç]ao)\b/.test(m)) {
    return result("Missão das estrelas ⭐ Se temos 2 estrelas e encontramos mais 3, quantas são ao todo?", [
      option("A: 4", "Resposta da missão de matemática: A"),
      option("B: 5", "Resposta da missão de matemática: B"),
      option("C: 6", "Resposta da missão de matemática: C")
    ], "quiz");
  }
  if (/\b(robo\w*|robotic\w*|eletronic\w*|sensor\w*|arduino)\b/.test(m)) {
    return result("Um robô combina peças, sensores e instruções. 🤖 O sensor percebe algo, e o programa decide o que fazer. Por exemplo: SE estiver escuro, ENTÃO acenda uma luz!", [
      option("Desafio de lógica 🧩", "Quero um desafio de lógica"),
      option("Aprender matemática ⭐", "Quero uma missão de matemática")
    ], "robotics");
  }
  if (/\b(senha|internet|seguranca|privacidade|hacker|hackear)\b/.test(m)) {
    return result("Na internet, proteja seus segredos! 🔒 Use senhas longas, nunca compartilhe códigos e peça ajuda a um adulto antes de abrir links desconhecidos. Hacking ético começa com permissão e respeito.", [
      option("Desafio de lógica 🧩", "Quero um desafio de lógica"),
      option("Conhecer robôs 🤖", "Como funciona um robô?")
    ], "security");
  }
  if (/\b(planeta|espaco|estrela|sol|lua|astronomia|ciencia)\b/.test(m)) {
    return result("A ciência é cheia de perguntas incríveis! 🌌 A Terra é um planeta que gira em torno do Sol. Quer usar matemática para contar estrelas?", [
      option("Contar estrelas ⭐", "Quero uma missão de matemática"), STARTERS[0]
    ], "science");
  }
  if (/\b(quem e voce|voce e humano|voce e real|como se chama)\b/.test(m)) {
    return result("Eu sou a Heart, uma lobinha virtual da Workshop Kids! 🐺 Sou um programa com respostas educativas, não sou uma pessoa e não sei tudo. Vamos aprender juntos?", STARTERS, "identity");
  }
  if (/\b(oi|ola|bom dia|boa tarde|boa noite|auuu|hello)\b/.test(m)) {
    return result("Auuuu! 🐺💜 Eu sou a Heart, sua guia de aventuras tecnológicas! Escolha uma missão para começar.", STARTERS, "hello");
  }
  return result("Que pergunta interessante! 🐺 Ainda estou aprendendo a guiar aventuras sobre alguns assuntos. Podemos explorar lógica, robótica, matemática, ciência ou segurança na internet.", STARTERS, "fallback");
}

return {answer,STARTERS};
})();


